window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["superhuman"]={html:"<div class=\"own-superhuman\">\n  <header class=\"sh-bar\" id=\"sh-top\">\n    <a class=\"sh-brand\" href=\"#sh-top\">\n      <span class=\"sh-mark\" aria-hidden=\"true\"></span>\n      <span class=\"sh-wordmark\">Northwind</span>\n    </a>\n    <nav class=\"sh-nav\" aria-label=\"Primary\">\n      <a href=\"#sh-features\">Features</a>\n      <a href=\"#sh-plans\">Plans</a>\n      <a href=\"#sh-enterprise\">Enterprise</a>\n    </nav>\n    <div class=\"sh-bar-right\">\n      <a class=\"sh-signin\" href=\"#\">Sign in</a>\n      <a class=\"sh-btn sh-btn-pill\" href=\"#\">Get started</a>\n    </div>\n  </header>\n\n  <section class=\"sh-hero\" aria-labelledby=\"sh-hero-h\">\n    <div class=\"sh-sky\" aria-hidden=\"true\"></div>\n    <div class=\"sh-hero-inner\">\n      <div class=\"sh-hero-copy\">\n        <p class=\"sh-eyebrow\">Operations, considered</p>\n        <h1 id=\"sh-hero-h\">The calm dashboard for every region you run</h1>\n        <p class=\"sh-hero-lead\">Northwind turns throughput, refunds, and delivery time into one quiet feed. Read it at a glance, act in a keystroke.</p>\n        <div class=\"sh-hero-cta\">\n          <a class=\"sh-btn sh-btn-pill\" href=\"#\">Get started</a>\n        </div>\n        <p class=\"sh-hero-fine\">Free for small teams &middot; no card required</p>\n      </div>\n      <div class=\"sh-portrait\" aria-hidden=\"true\">\n        <svg viewBox=\"0 0 460 560\" preserveAspectRatio=\"xMidYMax meet\">\n          <defs>\n            <linearGradient id=\"sh-fig\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n              <stop offset=\"0\" stop-color=\"#3a3560\"/>\n              <stop offset=\"1\" stop-color=\"#0e0c1f\"/>\n            </linearGradient>\n            <linearGradient id=\"sh-rim\" x1=\"1\" y1=\"0\" x2=\"0\" y2=\"1\">\n              <stop offset=\"0\" stop-color=\"#c9b4fa\"/>\n              <stop offset=\"1\" stop-color=\"#5a5772\" stop-opacity=\"0\"/>\n            </linearGradient>\n          </defs>\n          <ellipse cx=\"230\" cy=\"220\" rx=\"120\" ry=\"150\" fill=\"url(#sh-fig)\"/>\n          <path d=\"M120 560c0-96 50-168 110-168s110 72 110 168z\" fill=\"url(#sh-fig)\"/>\n          <path d=\"M338 120c28 40 30 130 -6 210\" fill=\"none\" stroke=\"url(#sh-rim)\" stroke-width=\"10\" stroke-linecap=\"round\"/>\n          <path d=\"M300 96c22 30 26 96 6 150\" fill=\"none\" stroke=\"#c9b4fa\" stroke-opacity=\".5\" stroke-width=\"4\" stroke-linecap=\"round\"/>\n        </svg>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"sh-features\" id=\"sh-features\" aria-labelledby=\"sh-feat-h\">\n    <div class=\"sh-feat-head\">\n      <h2 id=\"sh-feat-h\">Built for the way operators actually work</h2>\n      <div class=\"sh-tabs\" role=\"tablist\" aria-label=\"Categories\">\n        <button type=\"button\" class=\"sh-tab on\" role=\"tab\" aria-selected=\"true\">Regions</button>\n        <button type=\"button\" class=\"sh-tab\" role=\"tab\" aria-selected=\"false\">Orders</button>\n        <button type=\"button\" class=\"sh-tab\" role=\"tab\" aria-selected=\"false\">Alerts</button>\n        <button type=\"button\" class=\"sh-tab\" role=\"tab\" aria-selected=\"false\">Exports</button>\n      </div>\n    </div>\n    <div class=\"sh-feat-row\">\n      <div class=\"sh-feat-copy\">\n        <h3>A single feed for every store</h3>\n        <p>Each region gets one row: volume, trend, and a nudge when something drifts. No tabs, no charts to configure &mdash; the numbers are simply there when you look.</p>\n        <ul class=\"sh-feat-list\">\n          <li>Keyboard-first navigation across regions</li>\n          <li>Rolling 24-hour throughput on every row</li>\n          <li>Quiet notifications, grouped by store</li>\n        </ul>\n        <a class=\"sh-tlink\" href=\"#\">See how it works &rarr;</a>\n      </div>\n      <div class=\"sh-mock\" aria-hidden=\"true\">\n        <div class=\"sh-mock-bar\">\n          <span class=\"sh-mock-title\">Operations &middot; Today</span>\n          <span class=\"sh-mock-live\">Live</span>\n        </div>\n        <ul class=\"sh-rows\">\n          <li class=\"sh-row\">\n            <span class=\"sh-row-dot sh-dot-a\"></span>\n            <span class=\"sh-row-name\">North &mdash; Store 042</span>\n            <span class=\"sh-row-metric\">48,210</span>\n            <span class=\"sh-row-trend sh-up\">+4.2%</span>\n          </li>\n          <li class=\"sh-row\">\n            <span class=\"sh-row-dot sh-dot-b\"></span>\n            <span class=\"sh-row-name\">East &mdash; Store 118</span>\n            <span class=\"sh-row-metric\">61,553</span>\n            <span class=\"sh-row-trend sh-up\">+1.8%</span>\n          </li>\n          <li class=\"sh-row\">\n            <span class=\"sh-row-dot sh-dot-c\"></span>\n            <span class=\"sh-row-name\">South &mdash; Store 207</span>\n            <span class=\"sh-row-metric\">36,904</span>\n            <span class=\"sh-row-trend sh-down\">-0.9%</span>\n          </li>\n          <li class=\"sh-row\">\n            <span class=\"sh-row-dot sh-dot-d\"></span>\n            <span class=\"sh-row-name\">West &mdash; Store 331</span>\n            <span class=\"sh-row-metric\">29,108</span>\n            <span class=\"sh-row-trend sh-up\">+2.6%</span>\n          </li>\n        </ul>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"sh-split\" aria-labelledby=\"sh-split-h\">\n    <div class=\"sh-split-copy\">\n      <p class=\"sh-eyebrow sh-eyebrow-dark\">On the web, app, and warehouse</p>\n      <h2 id=\"sh-split-h\">One view, every surface</h2>\n      <p>Northwind syncs live across the dashboard, the mobile app, and your warehouse export. Start a review on your laptop, finish it from your phone between stores.</p>\n      <a class=\"sh-tlink\" href=\"#\">Explore sync &rarr;</a>\n    </div>\n    <div class=\"sh-split-art\" aria-hidden=\"true\">\n      <div class=\"sh-device sh-device-web\">\n        <div class=\"sh-device-bar\"><i></i><i></i><i></i></div>\n        <div class=\"sh-device-body\">\n          <div class=\"sh-mini\"><span class=\"lab\">Volume</span><b>184,904</b></div>\n          <div class=\"sh-mini\"><span class=\"lab\">Refunds</span><b>1,204</b></div>\n          <div class=\"sh-mini\"><span class=\"lab\">Latency</span><b>82 ms</b></div>\n        </div>\n      </div>\n      <div class=\"sh-device sh-device-phone\">\n        <div class=\"sh-phone-notch\"></div>\n        <div class=\"sh-phone-row\"><span>North</span><b>48.2k</b></div>\n        <div class=\"sh-phone-row\"><span>East</span><b>61.5k</b></div>\n        <div class=\"sh-phone-row\"><span>South</span><b>36.9k</b></div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"sh-plans\" id=\"sh-plans\" aria-labelledby=\"sh-plans-h\">\n    <div class=\"sh-plans-head\">\n      <p class=\"sh-eyebrow sh-eyebrow-dark\">Plans</p>\n      <h2 id=\"sh-plans-h\">Sober pricing, no surprises</h2>\n      <p>Every plan ships the full feed. Choose by the number of regions and how far back you look.</p>\n    </div>\n    <div class=\"sh-plan-grid\">\n      <article class=\"sh-plan\">\n        <h3>Starter</h3>\n        <p class=\"sh-plan-price\"><span>$0</span>/mo</p>\n        <p class=\"sh-plan-sub\">For one team and one region.</p>\n        <ul><li>1 region</li><li>7-day history</li><li>Web + mobile</li></ul>\n        <a class=\"sh-btn sh-btn-dark sh-btn-block\" href=\"#\">Start free</a>\n      </article>\n      <article class=\"sh-plan sh-plan-featured\">\n        <span class=\"sh-plan-flag\">Most popular</span>\n        <h3>Team</h3>\n        <p class=\"sh-plan-price\"><span>$30</span>/mo</p>\n        <p class=\"sh-plan-sub\">For multi-store operators.</p>\n        <ul><li>10 regions</li><li>12-month history</li><li>Warehouse export</li><li>Priority email</li></ul>\n        <a class=\"sh-btn sh-btn-on-indigo sh-btn-block\" href=\"#\">Choose Team</a>\n      </article>\n      <article class=\"sh-plan\">\n        <h3>Enterprise</h3>\n        <p class=\"sh-plan-price\"><span>Custom</span></p>\n        <p class=\"sh-plan-sub\">For regulated deployments.</p>\n        <ul><li>Unlimited regions</li><li>SSO &amp; audit log</li><li>Dedicated support</li></ul>\n        <a class=\"sh-btn sh-btn-dark sh-btn-block\" href=\"#\">Contact sales</a>\n      </article>\n    </div>\n  </section>\n\n  <section class=\"sh-teal\" id=\"sh-enterprise\" aria-labelledby=\"sh-teal-h\">\n    <div class=\"sh-teal-inner\">\n      <h2 id=\"sh-teal-h\">Bring every region into one quiet view</h2>\n      <p>Start today and watch throughput settle into place, one store at a time.</p>\n      <a class=\"sh-btn sh-btn-on-teal\" href=\"#\">Get started</a>\n    </div>\n  </section>\n\n  <footer class=\"sh-foot\">\n    <div class=\"sh-foot-grid\">\n      <div class=\"sh-foot-brand\">\n        <span class=\"sh-wordmark\">Northwind</span>\n        <p>Operations analytics for every region. Sample data, showcase only.</p>\n      </div>\n      <nav class=\"sh-foot-col\" aria-label=\"Product\"><h4>Product</h4><a href=\"#sh-features\">Features</a><a href=\"#sh-plans\">Plans</a><a href=\"#\">Changelog</a></nav>\n      <nav class=\"sh-foot-col\" aria-label=\"Company\"><h4>Company</h4><a href=\"#\">About</a><a href=\"#\">Careers</a><a href=\"#\">Press</a></nav>\n      <nav class=\"sh-foot-col\" aria-label=\"Support\"><h4>Support</h4><a href=\"#\">Help center</a><a href=\"#\">Status</a><a href=\"#\">Contact</a></nav>\n      <nav class=\"sh-foot-col\" aria-label=\"Legal\"><h4>Legal</h4><a href=\"#\">Privacy</a><a href=\"#\">Terms</a><a href=\"#\">Security</a></nav>\n    </div>\n    <div class=\"sh-foot-row\">\n      <span>&copy; 2026 Northwind &mdash; fictional brand</span>\n      <span class=\"sh-foot-social\" aria-label=\"Social\"><a href=\"#\" aria-label=\"X\">X</a><a href=\"#\" aria-label=\"GitHub\">GH</a></span>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ SUPERHUMAN — own layout for showcase.html ═════════════════════════════\n   Three-canvas system: indigo-navy editorial hero with a violet-sky backdrop\n   and a half-bleed portrait, a quiet white body, and a deep-teal closing band.\n   Super Sans VF is substituted with Inter at sub-default weights (460 / 540).\n   Scoped under `.own-superhuman`; responsive via @container frame. */\n\n.own-superhuman {\n  --sh-primary: #1b1938;\n  --sh-primary-deep: #0e0c1f;\n  --sh-on-primary: #ffffff;\n  --sh-ink: #292827;\n  --sh-ink-mute: #73706d;\n  --sh-ink-faint: #9a9794;\n  --sh-canvas: #ffffff;\n  --sh-canvas-soft: #fafaf8;\n  --sh-violet-soft: #c9b4fa;\n  --sh-teal-deep: #0e3030;\n  --sh-teal-mid: #155555;\n  --sh-hairline: #e8e4dd;\n  --sh-hairline-dark: #3f3a52;\n  --sh-on-dark-mute: #bcbac9;\n  --sh-on-dark-faint: #5a5772;\n\n  --sh-sans: 'Super Sans VF', system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif;\n\n  --sh-r-xs: 4px;\n  --sh-r-sm: 6px;\n  --sh-r-md: 8px;\n  --sh-r-lg: 12px;\n  --sh-r-xl: 16px;\n  --sh-r-full: 9999px;\n\n  position: relative;\n  background: var(--sh-canvas);\n  color: var(--sh-ink);\n  font-family: var(--sh-sans);\n  font-size: 16px;\n  line-height: 1.5;\n  font-weight: 460;\n  text-align: left;\n  -webkit-font-smoothing: antialiased;\n  border-radius: 13px;\n  overflow: clip;\n}\n\n.own-superhuman *,\n.own-superhuman *::before,\n.own-superhuman *::after { box-sizing: border-box; }\n\n.own-superhuman :focus-visible { outline: 3px solid var(--sh-violet-soft); outline-offset: 2px; border-radius: var(--sh-r-sm); }\n\n.own-superhuman h1, .own-superhuman h2, .own-superhuman h3, .own-superhuman h4 {\n  margin: 0; font-weight: 540; line-height: 1.14; letter-spacing: -.63px;\n}\n.own-superhuman h1 { line-height: .96; }\n.own-superhuman p { margin: 0; }\n.own-superhuman ul { margin: 0; padding: 0; list-style: none; }\n.own-superhuman a { color: inherit; text-decoration: none; }\n\n/* ── buttons — rounded rectangle, pill only on the hero ───────────────────── */\n.own-superhuman .sh-btn {\n  display: inline-flex; align-items: center; justify-content: center; gap: 8px;\n  font-family: var(--sh-sans); font-weight: 700; font-size: 16px; line-height: 1;\n  padding: 12px 20px; border-radius: var(--sh-r-md); border: 1px solid transparent;\n  cursor: pointer; white-space: nowrap; transition: background-color .2s, color .2s, border-color .2s;\n}\n.own-superhuman .sh-btn-pill { border-radius: var(--sh-r-full); background: var(--sh-violet-soft); color: var(--sh-primary); }\n.own-superhuman .sh-btn-pill:hover { background: #d8c9fb; }\n.own-superhuman .sh-btn-dark { background: var(--sh-primary); color: var(--sh-on-primary); }\n.own-superhuman .sh-btn-dark:hover { background: var(--sh-primary-deep); }\n.own-superhuman .sh-btn-on-indigo { background: var(--sh-canvas); color: var(--sh-primary); }\n.own-superhuman .sh-btn-on-indigo:hover { background: #eceaf5; }\n.own-superhuman .sh-btn-on-teal { background: var(--sh-canvas); color: var(--sh-teal-deep); }\n.own-superhuman .sh-btn-on-teal:hover { background: #efefec; }\n.own-superhuman .sh-btn-block { width: 100%; margin-top: auto; }\n.own-superhuman .sh-tlink { color: var(--sh-primary); font-weight: 540; font-size: 15px; text-decoration: underline; }\n.own-superhuman .sh-tlink:hover { color: var(--sh-teal-mid); }\n\n/* ── shared text ──────────────────────────────────────────────────────────── */\n.own-superhuman .sh-eyebrow { font-size: 12px; font-weight: 540; letter-spacing: .12em; text-transform: uppercase; color: var(--sh-violet-soft); margin-bottom: 14px; }\n.own-superhuman .sh-eyebrow-dark { color: var(--sh-teal-mid); }\n\n/* ── nav ──────────────────────────────────────────────────────────────────── */\n.own-superhuman .sh-bar {\n  position: sticky; top: 68px; z-index: 40;\n  display: flex; align-items: center; gap: 24px;\n  padding: 16px 24px; background: var(--sh-primary); color: #fff;\n}\n.own-superhuman .sh-brand { display: inline-flex; align-items: center; gap: 9px; }\n.own-superhuman .sh-mark {\n  width: 26px; height: 26px; border-radius: 50%;\n  background: linear-gradient(135deg, var(--sh-violet-soft), #6a5acd);\n}\n.own-superhuman .sh-wordmark { font-size: 19px; font-weight: 540; letter-spacing: -.4px; }\n.own-superhuman .sh-nav { display: flex; align-items: center; gap: 22px; margin-left: 6px; }\n.own-superhuman .sh-nav a { font-size: 15px; font-weight: 460; color: var(--sh-on-dark-mute); }\n.own-superhuman .sh-nav a:hover { color: #fff; }\n.own-superhuman .sh-bar-right { margin-left: auto; display: flex; align-items: center; gap: 16px; }\n.own-superhuman .sh-signin { font-size: 15px; font-weight: 460; color: #fff; }\n.own-superhuman .sh-signin:hover { color: var(--sh-violet-soft); }\n.own-superhuman .sh-bar .sh-btn-pill { padding: 10px 18px; font-size: 14px; }\n\n/* ── hero — indigo + violet-sky + half-bleed portrait ─────────────────────── */\n.own-superhuman .sh-hero { position: relative; background: var(--sh-primary); color: #fff; overflow: clip; }\n.own-superhuman .sh-sky {\n  position: absolute; inset: 0; z-index: 0;\n  background:\n    radial-gradient(60% 70% at 78% 22%, rgba(201, 180, 250, .55), transparent 62%),\n    radial-gradient(50% 60% at 60% 80%, rgba(21, 85, 85, .5), transparent 68%),\n    radial-gradient(80% 90% at 20% 10%, rgba(63, 58, 82, .8), transparent 70%);\n}\n.own-superhuman .sh-hero-inner {\n  position: relative; z-index: 1;\n  display: grid; grid-template-columns: 1.05fr .95fr; align-items: end; gap: 32px;\n  max-width: 1100px; margin: 0 auto; padding: 80px 40px 0;\n}\n.own-superhuman .sh-hero-copy { padding-bottom: 72px; max-width: 33ch; }\n.own-superhuman .sh-hero h1 { font-size: clamp(40px, 5cqi, 64px); font-weight: 540; line-height: .96; color: #fff; }\n.own-superhuman .sh-hero-lead { font-size: 18px; font-weight: 460; line-height: 1.5; color: var(--sh-on-dark-mute); margin: 20px 0 28px; max-width: 44ch; }\n.own-superhuman .sh-hero-cta { display: flex; gap: 12px; }\n.own-superhuman .sh-hero-fine { font-size: 13px; color: var(--sh-on-dark-faint); margin-top: 16px; }\n.own-superhuman .sh-portrait { position: relative; align-self: end; }\n.own-superhuman .sh-portrait svg { display: block; width: 100%; height: auto; max-height: 480px; }\n\n/* ── features ─────────────────────────────────────────────────────────────── */\n.own-superhuman .sh-features { padding: 72px 40px; max-width: 1100px; margin: 0 auto; }\n.own-superhuman .sh-feat-head { margin-bottom: 36px; }\n.own-superhuman .sh-feat-head h2 { font-size: clamp(28px, 3.2cqi, 40px); font-weight: 540; letter-spacing: -.63px; max-width: 20ch; }\n.own-superhuman .sh-tabs { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 22px; }\n.own-superhuman .sh-tab {\n  font-family: var(--sh-sans); font-size: 14px; font-weight: 600; color: var(--sh-ink);\n  padding: 8px 16px; border-radius: var(--sh-r-full); border: 1px solid var(--sh-hairline);\n  background: #fff; cursor: pointer; transition: background-color .15s, color .15s, border-color .15s;\n}\n.own-superhuman .sh-tab:hover { border-color: var(--sh-ink-faint); }\n.own-superhuman .sh-tab.on { background: var(--sh-primary); color: #fff; border-color: var(--sh-primary); }\n.own-superhuman .sh-feat-row { display: grid; grid-template-columns: 1fr 1.05fr; gap: 48px; align-items: center; }\n.own-superhuman .sh-feat-copy h3 { font-size: 28px; font-weight: 540; letter-spacing: -.63px; }\n.own-superhuman .sh-feat-copy p { font-size: 16px; line-height: 1.55; color: var(--sh-ink-mute); margin: 16px 0 20px; max-width: 46ch; }\n.own-superhuman .sh-feat-list { display: grid; gap: 11px; margin-bottom: 22px; }\n.own-superhuman .sh-feat-list li { font-size: 15px; color: var(--sh-ink); padding-left: 24px; position: relative; }\n.own-superhuman .sh-feat-list li::before {\n  content: ''; position: absolute; left: 0; top: 4px; width: 15px; height: 15px; border-radius: 50%;\n  background: var(--sh-violet-soft);\n}\n.own-superhuman .sh-mock {\n  background: var(--sh-canvas-soft); border: 1px solid var(--sh-hairline); border-radius: var(--sh-r-lg);\n  padding: 8px; box-shadow: 0 8px 24px rgba(0, 0, 0, .06);\n}\n.own-superhuman .sh-mock-bar { display: flex; align-items: center; justify-content: space-between; padding: 12px 14px; }\n.own-superhuman .sh-mock-title { font-size: 14px; font-weight: 600; color: var(--sh-ink); }\n.own-superhuman .sh-mock-live { font-size: 11px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; color: var(--sh-teal-mid); }\n.own-superhuman .sh-mock-live::before { content: ''; display: inline-block; width: 7px; height: 7px; border-radius: 50%; background: var(--sh-teal-mid); margin-right: 5px; vertical-align: middle; }\n.own-superhuman .sh-rows { display: grid; gap: 4px; }\n.own-superhuman .sh-row {\n  display: grid; grid-template-columns: auto 1fr auto auto; gap: 12px; align-items: center;\n  padding: 13px 14px; background: #fff; border: 1px solid var(--sh-hairline); border-radius: var(--sh-r-md);\n}\n.own-superhuman .sh-row-dot { width: 10px; height: 10px; border-radius: 50%; display: block; }\n.own-superhuman .sh-dot-a { background: #c9b4fa; }\n.own-superhuman .sh-dot-b { background: #155555; }\n.own-superhuman .sh-dot-c { background: #bb9a6f; }\n.own-superhuman .sh-dot-d { background: #5a5772; }\n.own-superhuman .sh-row-name { font-size: 14.5px; font-weight: 460; color: var(--sh-ink); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.own-superhuman .sh-row-metric { font-size: 15px; font-weight: 600; font-variant-numeric: tabular-nums; color: var(--sh-ink); }\n.own-superhuman .sh-row-trend { font-size: 13px; font-weight: 600; font-variant-numeric: tabular-nums; }\n.own-superhuman .sh-up { color: var(--sh-teal-mid); }\n.own-superhuman .sh-down { color: #a05b57; }\n\n/* ── split band ───────────────────────────────────────────────────────────── */\n.own-superhuman .sh-split {\n  display: grid; grid-template-columns: 1fr 1.1fr; gap: 48px; align-items: center;\n  background: var(--sh-canvas-soft); border-top: 1px solid var(--sh-hairline); border-bottom: 1px solid var(--sh-hairline);\n  padding: 72px 40px;\n}\n.own-superhuman .sh-split-copy { max-width: 520px; margin-left: auto; width: 100%; }\n.own-superhuman .sh-split h2 { font-size: clamp(28px, 3.2cqi, 40px); font-weight: 540; letter-spacing: -.63px; max-width: 18ch; }\n.own-superhuman .sh-split p { font-size: 16px; line-height: 1.55; color: var(--sh-ink-mute); margin: 16px 0 20px; max-width: 46ch; }\n.own-superhuman .sh-split-art { position: relative; min-height: 300px; max-width: 520px; }\n.own-superhuman .sh-device { border: 1px solid var(--sh-hairline); border-radius: var(--sh-r-lg); background: #fff; box-shadow: 0 8px 24px rgba(0, 0, 0, .06); overflow: hidden; }\n.own-superhuman .sh-device-web { width: 78%; }\n.own-superhuman .sh-device-bar { display: flex; gap: 6px; padding: 11px 12px; background: var(--sh-canvas-soft); border-bottom: 1px solid var(--sh-hairline); }\n.own-superhuman .sh-device-bar i { width: 9px; height: 9px; border-radius: 50%; background: var(--sh-hairline); display: block; }\n.own-superhuman .sh-device-body { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; padding: 16px; }\n.own-superhuman .sh-mini { display: grid; gap: 3px; }\n.own-superhuman .sh-mini .lab { font-size: 11px; letter-spacing: .04em; text-transform: uppercase; color: var(--sh-ink-faint); }\n.own-superhuman .sh-mini b { font-size: 20px; font-weight: 600; letter-spacing: -.4px; font-variant-numeric: tabular-nums; color: var(--sh-ink); }\n.own-superhuman .sh-device-phone {\n  position: absolute; right: 0; bottom: -24px; width: 34%; padding: 20px 14px 16px;\n}\n.own-superhuman .sh-phone-notch { width: 44px; height: 5px; border-radius: 3px; background: var(--sh-hairline-dark); margin: 0 auto 14px; }\n.own-superhuman .sh-phone-row { display: flex; justify-content: space-between; padding: 7px 0; border-bottom: 1px solid var(--sh-hairline); font-size: 13px; }\n.own-superhuman .sh-phone-row:last-child { border-bottom: 0; }\n.own-superhuman .sh-phone-row span { color: var(--sh-ink-mute); }\n.own-superhuman .sh-phone-row b { font-weight: 600; font-variant-numeric: tabular-nums; color: var(--sh-ink); }\n\n/* ── plans ────────────────────────────────────────────────────────────────── */\n.own-superhuman .sh-plans { padding: 72px 40px; max-width: 1100px; margin: 0 auto; }\n.own-superhuman .sh-plans-head { margin-bottom: 40px; max-width: 60ch; }\n.own-superhuman .sh-plans-head h2 { font-size: clamp(28px, 3.2cqi, 40px); font-weight: 540; letter-spacing: -.63px; }\n.own-superhuman .sh-plans-head p { font-size: 16px; color: var(--sh-ink-mute); margin-top: 14px; }\n.own-superhuman .sh-plan-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; align-items: stretch; }\n.own-superhuman .sh-plan {\n  position: relative; background: #fff; border: 1px solid var(--sh-hairline); border-radius: var(--sh-r-lg);\n  padding: 32px; display: flex; flex-direction: column; gap: 6px; box-shadow: 0 1px 3px rgba(0, 0, 0, .08);\n}\n.own-superhuman .sh-plan h3 { font-size: 20px; font-weight: 540; letter-spacing: -.4px; }\n.own-superhuman .sh-plan-price { font-size: 22px; font-weight: 540; letter-spacing: -.315px; margin: 10px 0 4px; font-variant-numeric: tabular-nums; }\n.own-superhuman .sh-plan-price span { font-size: 48px; font-weight: 460; letter-spacing: -1.32px; }\n.own-superhuman .sh-plan-sub { font-size: 14px; color: var(--sh-ink-mute); margin-bottom: 16px; }\n.own-superhuman .sh-plan ul { display: grid; gap: 10px; margin-bottom: 26px; }\n.own-superhuman .sh-plan li { font-size: 15px; color: var(--sh-ink); padding-left: 22px; position: relative; }\n.own-superhuman .sh-plan li::before { content: ''; position: absolute; left: 0; top: 8px; width: 8px; height: 8px; border-radius: 50%; background: var(--sh-violet-soft); }\n.own-superhuman .sh-plan-featured { background: var(--sh-primary); border-color: var(--sh-primary); color: #fff; }\n.own-superhuman .sh-plan-featured h3, .own-superhuman .sh-plan-featured .sh-plan-price { color: #fff; }\n.own-superhuman .sh-plan-featured .sh-plan-sub { color: var(--sh-on-dark-mute); }\n.own-superhuman .sh-plan-featured li { color: var(--sh-on-dark-mute); }\n.own-superhuman .sh-plan-flag {\n  position: absolute; top: 18px; right: 18px; font-size: 11px; font-weight: 600; letter-spacing: .06em;\n  text-transform: uppercase; color: var(--sh-primary); background: var(--sh-violet-soft); border-radius: var(--sh-r-full);\n  padding: 4px 10px;\n}\n\n/* ── closing teal band ────────────────────────────────────────────────────── */\n.own-superhuman .sh-teal { background: var(--sh-teal-deep); color: #fff; padding: 96px 40px; }\n.own-superhuman .sh-teal-inner { max-width: 900px; margin: 0 auto; text-align: center; }\n.own-superhuman .sh-teal h2 { font-size: clamp(28px, 3.6cqi, 44px); font-weight: 540; letter-spacing: -.63px; line-height: 1.14; color: #fff; }\n.own-superhuman .sh-teal p { font-size: 18px; font-weight: 460; color: rgba(255, 255, 255, .78); margin: 18px auto 28px; max-width: 52ch; }\n\n/* ── footer ───────────────────────────────────────────────────────────────── */\n.own-superhuman .sh-foot { padding: 64px 40px 32px; background: #fff; border-top: 1px solid var(--sh-hairline); }\n.own-superhuman .sh-foot-grid { display: grid; grid-template-columns: 1.6fr repeat(4, 1fr); gap: 32px; max-width: 1100px; margin: 0 auto; }\n.own-superhuman .sh-foot-brand p { font-size: 14px; color: var(--sh-ink-mute); margin-top: 12px; max-width: 32ch; }\n.own-superhuman .sh-foot-col { display: grid; gap: 10px; align-content: start; }\n.own-superhuman .sh-foot-col h4 { font-size: 14px; font-weight: 600; letter-spacing: 0; }\n.own-superhuman .sh-foot-col a { font-size: 14px; color: var(--sh-ink-mute); }\n.own-superhuman .sh-foot-col a:hover { color: var(--sh-teal-mid); }\n.own-superhuman .sh-foot-row {\n  display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap; align-items: center;\n  max-width: 1100px; margin: 40px auto 0; padding-top: 20px; border-top: 1px solid var(--sh-hairline);\n  font-size: 14px; color: var(--sh-ink-mute);\n}\n.own-superhuman .sh-foot-social { display: flex; gap: 12px; }\n.own-superhuman .sh-foot-social a {\n  display: grid; place-items: center; width: 30px; height: 30px; border-radius: 50%;\n  border: 1px solid var(--sh-hairline); font-size: 11px; color: var(--sh-ink-mute);\n}\n.own-superhuman .sh-foot-social a:hover { border-color: var(--sh-teal-mid); color: var(--sh-teal-mid); }\n\n/* ── responsive ───────────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-superhuman .sh-nav { display: none; }\n  .own-superhuman .sh-hero-inner { grid-template-columns: 1fr; padding: 56px 32px 0; }\n  .own-superhuman .sh-hero-copy { padding-bottom: 32px; max-width: none; }\n  .own-superhuman .sh-portrait { max-width: 360px; margin: 0 auto; }\n  .own-superhuman .sh-feat-row,\n  .own-superhuman .sh-split { grid-template-columns: 1fr; gap: 32px; }\n  .own-superhuman .sh-split-copy { margin: 0; }\n  .own-superhuman .sh-plan-grid { grid-template-columns: 1fr 1fr; }\n  .own-superhuman .sh-foot-grid { grid-template-columns: 1fr 1fr 1fr; gap: 24px; }\n}\n@container frame (max-width: 760px) {\n  .own-superhuman .sh-bar { top: 10px; padding: 12px 16px; }\n  .own-superhuman .sh-signin { display: none; }\n  .own-superhuman .sh-hero-inner { padding: 40px 18px 0; }\n  .own-superhuman .sh-features,\n  .own-superhuman .sh-split,\n  .own-superhuman .sh-plans,\n  .own-superhuman .sh-teal,\n  .own-superhuman .sh-foot { padding-left: 18px; padding-right: 18px; }\n  .own-superhuman .sh-plan-grid { grid-template-columns: 1fr; }\n  .own-superhuman .sh-foot-grid { grid-template-columns: 1fr 1fr; }\n  .own-superhuman .sh-teal { padding-top: 64px; padding-bottom: 64px; }\n  .own-superhuman .sh-device-phone { position: static; width: 60%; margin: 14px 0 0 auto; }\n  .own-superhuman .sh-split-art { min-height: 0; }\n}\n@container frame (max-width: 430px) {\n  .own-superhuman .sh-hero h1 { font-size: 34px; }\n  .own-superhuman .sh-row { grid-template-columns: auto 1fr auto; }\n  .own-superhuman .sh-row-trend { grid-column: 2 / 4; text-align: right; }\n  .own-superhuman .sh-device-body { grid-template-columns: 1fr; }\n  .own-superhuman .sh-foot-grid { grid-template-columns: 1fr; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .own-superhuman *, .own-superhuman *::before, .own-superhuman *::after {\n    transition-duration: .001ms !important;\n    animation-duration: .001ms !important;\n  }\n}\n"};
/* ══ SUPERHUMAN — behaviour for showcase.html ═══════════════════════════════
   Registers window.OWN_LAYOUTS['superhuman'].init(root). Wires the feature
   category tabs and a soft reveal on the mock and plan cards. Listeners are
   bound to an AbortController; the observer is disconnected on cleanup. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  OWN['superhuman'] = {
    init: function (root) {
      var reduced = false;
      try { reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { /* ignore */ }

      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      var io = null;

      var tabs = root.querySelectorAll('.sh-tab');
      tabs.forEach(function (tab) {
        tab.addEventListener('click', function () {
          tabs.forEach(function (t) {
            var on = t === tab;
            t.classList.toggle('on', on);
            t.setAttribute('aria-selected', on ? 'true' : 'false');
          });
        }, signal ? { signal: signal } : undefined);
      });

      if (!reduced && typeof IntersectionObserver !== 'undefined') {
        var targets = root.querySelectorAll('.sh-mock, .sh-plan, .sh-device');
        io = new IntersectionObserver(function (entries) {
          entries.forEach(function (entry) {
            if (entry.isIntersecting) {
              entry.target.style.opacity = '1';
              entry.target.style.transform = 'none';
              io.unobserve(entry.target);
            }
          });
        }, { root: null, rootMargin: '0px 0px -6% 0px', threshold: 0.06 });

        targets.forEach(function (el) {
          el.style.opacity = '0';
          el.style.transform = 'translateY(16px)';
          el.style.transition = 'opacity .55s ease, transform .55s ease';
          io.observe(el);
        });
      }

      return function cleanup() {
        if (AC) { try { AC.abort(); } catch (e) { /* ignore */ } }
        if (io) { try { io.disconnect(); } catch (e) { /* ignore */ } }
      };
    }
  };
})();
